function xtSeed(){return{version:1,folders:[{id:'xt-system',name:'系统模板',parent:null,system:true},{id:'xt-nonconstruction',name:'非施工合同',parent:'xt-system',system:true},{id:'xt-construction',name:'施工合同',parent:'xt-system',system:true},{id:'xt-invoice',name:'发票',parent:'xt-system',system:true},{id:'xt-invoice-general',name:'普通发票',parent:'xt-invoice',system:true},{id:'xt-invoice-special',name:'专用发票',parent:'xt-invoice',system:true},{id:'xt-compliance',name:'合同条款',parent:'xt-system',system:true},{id:'xt-personal',name:'个人模板',parent:null,system:false,owner:xtIdentity()},{id:'xt-mine',name:'我的模板',parent:'xt-personal',system:false,owner:xtIdentity()},{id:'xt-meetings',name:'会议资料',parent:'xt-mine',system:false,owner:xtIdentity()},{id:'xt-payments',name:'票据核验',parent:'xt-mine',system:false,owner:xtIdentity()}],system:[{id:'sys-extract',name:'通用资料信息提取',folderId:'xt-system',description:'提取资料的基本事项、单位、金额与时间，供审计线索整理使用。',rules:tool('extract').fields.map(name=>xtRule(name,'提取原文中的'+name+'，保留原始单位及限定条件；无法取得时标注未提取到。'))},{id:'xt-sys-construction-full',name:'施工合同信息提取',folderId:'xt-construction',description:'覆盖项目主体、合同价款、工期、付款、变更及履约条款。',rules:xtRules(xtConstructionNames)},{id:'xt-sys-construction-summary',name:'施工合同要素摘要',folderId:'xt-construction',description:'快速整理施工合同的12项主要信息。',rules:xtRules(xtConstructionNames.slice(0,12))},{id:'xt-sys-invoice',name:'发票信息提取',folderId:'xt-invoice-general',description:'核对购销双方、发票号码、金额、税额与开票日期。',rules:xtRules(['发票名称','发票代码','发票号码','开票日期','购买方名称','购买方税号','销售方名称','销售方税号','货物或服务名称','规格型号','数量','不含税金额','税率','税额','价税合计','备注'])},{id:'xt-sys-nonconstruction-text',name:'非施工合同条款摘录',folderId:'xt-compliance',description:'按原文摘录合同主要条款，保留条款编号与约束条件。',rules:[xtRule('合同主要条款','摘录合同主体、标的、价款、履行、违约及争议解决相关条款原文；保留条款编号，不作合规性结论。')]},{id:'xt-sys-nonconstruction',name:'非施工合同信息提取',folderId:'xt-nonconstruction',description:'适用于采购与服务合同，提取主体、标的、付款及交付条件。',rules:xtRules(['合同名称','合同编号','合同类型','项目名称','采购方','供应方','签订日期','合同金额','币种','采购内容','数量','规格要求','服务范围','交付地点','交付期限','验收标准','付款方式','付款条件','发票要求','履约保证金','质保期限','违约责任','争议解决方式','合同生效条件'])}]};}
let xtCatalog;try{xtCatalog=JSON.parse(localStorage.getItem(XT_STORE));if(!xtCatalog||xtCatalog.version!==1||!Array.isArray(xtCatalog.folders)||!Array.isArray(xtCatalog.system))xtCatalog=null;}catch{}
if(!xtCatalog){xtCatalog=xtSeed();if(!state.templates.some(t=>t.toolId==='extract'))state.templates.push({id:'xt-my-meeting',toolId:'extract',name:'会议纪要要素提取',description:'整理会议名称、时间、参会人员及决议事项。',folderId:'xt-meetings',rules:[xtRule('会议名称','本次会议的名称。'),xtRule('会议时间','本次会议开始时间，保留原始日期。'),xtRule('参会人员','参会人员姓名及职务；多个人员分开列出。'),xtRule('决议事项','逐项提取会议形成的决议及责任单位。')],owner:xtIdentity(),prompt:'依据原文逐项提取，未载明的内容如实标注。'},{id:'xt-my-invoice',toolId:'extract',name:'票据报销要素提取',description:'核对单位、税号、含税金额与开票日期。',folderId:'xt-payments',rules:[xtRule('单位','提取发票抬头单位名称。'),xtRule('税号','单位纳税人识别号。'),xtRule('发票金额','发票金额（含税），保留币种及单位。'),xtRule('开票时间')],owner:xtIdentity(),prompt:'依据发票原文提取，不补充缺失信息。'});}
let xtView={folder:'xt-system',query:'',draftQuery:'',page:1,size:15,closed:[],mobileTree:false,folderQuery:''};try{Object.assign(xtView,JSON.parse(localStorage.getItem(XT_PREFS)||'{}'));}catch{}
function xtFolder(id){return xtCatalog.folders.find(f=>f.id===id);}
function xtPath(id){const names=[],seen=new Set();for(let f=xtFolder(id);f&&!seen.has(f.id);f=xtFolder(f.parent)){seen.add(f.id);names.unshift(f.name);}return names.join(' / ');}
function xtUnder(id,parent){const seen=new Set();for(let f=xtFolder(id);f&&!seen.has(f.id);f=xtFolder(f.parent)){if(f.id===parent)return true;seen.add(f.id);}return false;}
function xtFolderEdit(f){return !!f&&(f.system?xtAdmin():!f.owner||f.owner===xtIdentity());}
function xtAll(){return[...xtCatalog.system.map(t=>({...t,toolId:'extract',system:true})),...state.templates.filter(t=>t.toolId==='extract')];}
function xtFind(id){return xtAll().find(t=>t.id===id);}
function xtFields(t){const rows=t?.rules||t?.config?.fieldDefs||t?.config?.fields?.map(n=>({name:n,description:''}))||[];return rows.map(r=>({name:String(r.name??r.field_name??''),description:String(r.description??r.field_description??'')}));}
function xtCanEdit(t){return !!t&&(t.system?xtAdmin():(!t.owner||t.owner===xtIdentity())&&xtFolderEdit(xtFolder(t.folderId||'xt-mine')));}
function xtPersist(){try{localStorage.setItem(XT_STORE,JSON.stringify(xtCatalog));localStorage.setItem(XT_PREFS,JSON.stringify(xtView));}catch{toast('模板存储空间不足，请导出配置备份。');}persist();}
function xtList(){const q=xtView.query.trim().toLowerCase();return xtAll().filter(t=>xtUnder(t.folderId||'xt-mine',xtView.folder)&&(!q||t.name.toLowerCase().includes(q)));}
function xtPersonalOptions(selected){return xtCatalog.folders.filter(f=>!f.system&&xtFolderEdit(f)).map(f=>'<option value="'+E(f.id)+'" '+(f.id===selected?'selected':'')+'>'+E(xtPath(f.id))+'</option>').join('');}
function xtTarget(){const f=xtFolder(xtView.folder);return xtFolderEdit(f)?f.id:'xt-mine';}
function xtRefresh(){xtPersist();render();}
function xtFolderVisible(f){const q=(xtView.folderQuery||'').trim().toLowerCase();return !q||xtCatalog.folders.some(x=>xtUnder(x.id,f.id)&&x.name.toLowerCase().includes(q))||xtCatalog.folders.some(x=>xtUnder(f.id,x.id)&&x.name.toLowerCase().includes(q));}
function xtTree(parent=null,depth=0){return xtCatalog.folders.filter(f=>f.parent===parent&&xtFolderVisible(f)).map(f=>{const children=xtCatalog.folders.some(c=>c.parent===f.id&&xtFolderVisible(c)),closed=!xtView.folderQuery&&xtView.closed.includes(f.id),count=xtAll().filter(t=>xtUnder(t.folderId||'xt-mine',f.id)).length;return '<div class="xt-tree-row '+(f.id===xtView.folder?'selected':'')+'" style="--xt-depth:'+depth+'"><button class="xt-tree-expand" data-action="xt-toggle-folder" data-id="'+E(f.id)+'" aria-label="'+(closed?'展开':'收起')+E(f.name)+'" aria-expanded="'+!closed+'" '+(!children?'disabled':'')+'>'+(children?I(closed?'chevron':'down','icon-sm'):'')+'</button><button class="xt-tree-name" data-action="xt-folder" data-id="'+E(f.id)+'" title="'+E(xtPath(f.id))+'">'+I('folder','icon-sm')+'<span>'+E(f.name)+'</span><small title="含下级分类共 '+count+' 个模板">'+count+'</small></button>'+(xtFolderEdit(f)?'<details class="lib-dropdown xt-folder-dropdown"><summary class="iconbtn xt-folder-more" aria-label="管理分类 '+E(f.name)+'" title="管理分类 '+E(f.name)+'">'+I('more','icon-sm')+'</summary><div class="lib-menu">'+B(I('folderPlus','icon-sm')+'新建子分类','xt-new-folder','ghost sm','data-id="'+E(f.id)+'"')+(f.parent?B(I('edit','icon-sm')+'重命名','xt-rename-folder','ghost sm','data-id="'+E(f.id)+'"')+'<div class="xt-menu-divider"></div>'+B(I('trash','icon-sm')+'删除分类','xt-delete-folder','ghost danger sm','data-id="'+E(f.id)+'"'):'')+'</div></details>':'')+'</div>'+(!closed?xtTree(f.id,depth+1):'');}).join('');}
function xtCrumbs(id){const chain=[],seen=new Set();for(let f=xtFolder(id);f&&!seen.has(f.id);f=xtFolder(f.parent)){seen.add(f.id);chain.unshift(f);}return chain.map((f,i)=>(i?I('chevron','icon-sm'):'')+(i===chain.length-1?'<span aria-current="location">'+E(f.name)+'</span>':A(E(f.name),'xt-folder','data-id="'+E(f.id)+'"'))).join('');}
state.templates.filter(t=>t.toolId==='extract').forEach(t=>{if(!xtFolder(t.folderId))t.folderId='xt-mine';});
if(!xtFolder(xtView.folder))xtView.folder='xt-system';xtPersist();
sidebar=function(){const node=document.createElement('div');node.innerHTML=xtBase.sidebar();const b=node.querySelector('[data-action="nav-templates"]');if(b){b.title='提取模板';const label=b.querySelector('.nav-label');if(label)label.textContent='提取模板';}return node.innerHTML;};
getTemplate=function(id){return xtFind(id)||xtBase.getTemplate(id);};
templatesPage=function(){const list=xtList(),pages=Math.max(1,Math.ceil(list.length/xtView.size));xtView.page=Math.max(1,Math.min(xtView.page,pages));const f=xtFolder(xtView.folder);requestAnimationFrame(()=>{const crumbs=$('.xt-current-folder');if(crumbs)crumbs.scrollLeft=crumbs.scrollWidth;});return'<div class="xt-page" aria-label="提取模板"><h1 class="xt-sr-only">提取模板</h1><section class="xt-browser card"><aside class="xt-classifications '+(xtView.mobileTree?'mobile-open':'')+'" aria-label="模板分类"><div class="xt-category-head"><h2>模板分类</h2><div class="row gap4">'+B(I('refresh','icon-sm'),'xt-refresh','ghost sm','aria-label="刷新模板分类" title="刷新分类与模板"')+B(I('close','icon-sm'),'xt-close-tree','ghost sm xt-mobile-only','aria-label="关闭模板分类"')+'</div></div><div class="xt-category-search"><input id="xt-folder-query" type="search" aria-label="查找模板分类" placeholder="查找分类" data-xt-input="folder-query" value="'+E(xtView.folderQuery||'')+'"></div><div class="xt-tree-scroll">'+(xtTree()||'<p class="xt-tree-empty">没有匹配的分类</p>')+'</div><div class="xt-category-note" title="提取模板定义输出字段与取值口径，系统模板可复制后调整。"><span>提取模板</span><span>共 <strong>'+xtAll().length+'</strong> 个</span></div></aside><section class="xt-main"><div class="xt-toolbar"><div class="xt-page-location">'+B(I('folderTree','icon-sm'),'xt-open-tree','ghost sm xt-mobile-only','aria-label="选择模板分类"')+'<span class="audit-location-label">当前目录</span><div class="xt-current-folder" aria-label="当前模板分类" title="'+E(xtPath(f.id))+'">'+xtCrumbs(f.id)+'</div></div><div class="xt-search">'+B(I('search','icon-sm'),'xt-search','ghost sm','aria-label="查询模板" title="查询模板"')+'<input id="xt-template-query" placeholder="搜索模板名称" aria-label="搜索模板名称" data-xt-input="query" value="'+E(xtView.draftQuery)+'"></div>'+B(I('plus','icon-sm')+'新建模板','xt-new','primary sm')+'<details class="lib-dropdown xt-page-more"><summary class="btn sm" aria-label="更多模板操作">更多'+I('down','icon-sm')+'</summary><div class="lib-menu">'+B(I('upload','icon-sm')+'导入配置','v2-template-import','ghost sm')+'</div></details></div><div class="xt-table-scroll"><table class="table xt-table"><thead><tr><th>模板名称</th><th>描述</th><th>字段数</th><th>操作</th></tr></thead><tbody>'+pageItems(list,xtView.page,xtView.size).map(t=>'<tr data-template-id="'+E(t.id)+'"><td><div class="xt-template-name-wrap"><span class="xt-template-symbol">'+I('book')+'</span><div class="xt-template-name-main"><button class="filename" data-action="xt-fields" data-id="'+E(t.id)+'" title="'+E(t.name)+'">'+E(t.name)+'</button><div class="xt-template-location" title="'+E(xtPath(t.folderId||'xt-mine'))+'">'+E(xtPath(t.folderId||'xt-mine'))+'</div></div></div></td><td class="xt-template-description" title="'+E(t.description||'')+'"><span class="xt-description-text">'+E(t.description||'—')+'</span></td><td><button class="link xt-field-count" data-action="xt-fields" data-id="'+E(t.id)+'" aria-label="查看 '+E(t.name)+' 的 '+xtFields(t).length+' 个字段" title="查看字段与提取说明"><strong>'+xtFields(t).length+'</strong><span> 个</span></button></td><td class="xt-table-actions"><div class="row">'+A('使用模板','xt-use','data-id="'+E(t.id)+'"')+A('复制模板','xt-copy','data-id="'+E(t.id)+'" title="复制为个人模板，保留原模板"')+A('导出配置','xt-export','data-id="'+E(t.id)+'"')+(xtCanEdit(t)?'<details class="lib-dropdown"><summary class="iconbtn" aria-label="'+E(t.name)+' 更多操作">'+I('more','icon-sm')+'</summary><div class="lib-menu">'+B(I('edit','icon-sm')+'编辑模板','xt-edit','ghost sm','data-id="'+E(t.id)+'"')+'<div class="xt-menu-divider"></div>'+B(I('trash','icon-sm')+'删除模板','xt-delete','ghost danger sm','data-id="'+E(t.id)+'"')+'</div></details>':'')+'</div></td></tr>').join('')+(!list.length?'<tr><td colspan="4"><div class="xt-empty">'+I('book')+'<h3>'+(xtView.query?'没有匹配的模板':'此分类暂无模板')+'</h3><p>'+(xtView.query?'调整名称搜索条件，或选择其他分类。':'新建提取模板，或从系统模板复制后调整字段。')+'</p>'+B(xtView.query?'清除搜索':'新建模板',xtView.query?'xt-clear-search':'xt-new','soft sm mt')+'</div></td></tr>':'')+'</tbody></table></div><footer class="xt-pagination"><span>共 <strong>'+list.length+'</strong> 个模板<span class="xt-scope-note"> · 含下级分类</span></span><div class="row"><select aria-label="模板每页数量" data-xt-change="size">'+[10,15,20,50].map(n=>'<option value="'+n+'" '+(n===xtView.size?'selected':'')+'>'+n+' 条/页</option>').join('')+'</select>'+B(I('back','icon-sm'),'xt-prev','sm','aria-label="模板上一页" '+(xtView.page<=1?'disabled':''))+'<span>'+xtView.page+' / '+pages+'</span>'+B(I('chevron','icon-sm'),'xt-next','sm','aria-label="模板下一页" '+(xtView.page>=pages?'disabled':''))+'<label class="xt-page-jump">前往 <input type="number" min="1" max="'+pages+'" value="'+xtView.page+'" data-xt-change="page" aria-label="跳转模板页码"> 页</label></div></footer></section></section></div>';};
function xtOpenEditor(t=null,copy=false,from=null){$('#toast')?.classList.remove('show');if(t&&!copy&&!xtCanEdit(t))return toast('当前没有修改此模板的权限。');const folderId=t&&!copy?(t.folderId||'xt-mine'):copy?'xt-mine':xtTarget(),name=copy?xtUniqueName(t.name+' · 我的版本',folderId):t?.name||'',draft={id:copy?null:t?.id||null,folderId,name,description:t?.description||'',rules:t?xtFields(t):[xtRule('')],copySource:copy?t.id:null,prompt:t?.prompt||'',config:t?.config?structuredClone(t.config):null};openModal('xt-editor',{draft,initial:JSON.stringify(draft),error:'',from,listScroll:$('.xt-table-scroll')?.scrollTop||0});}
function xtUniqueName(name,folderId,exclude=null){let n=name,i=2;while(xtAll().some(t=>t.id!==exclude&&(t.folderId||'xt-mine')===folderId&&t.name===n))n=name+' '+i++;return n;}
function xtError(message,field){modalData.error=message;const el=$('#xt-editor-error');if(el)el.textContent=message;if(field){const node=$(field);node?.focus();node?.scrollIntoView({block:'nearest'});}return false;}
function xtValidateDraft(d){if(!d.name.trim())return xtError('请填写模板名称。','#xt-template-name');if(!xtFolderEdit(xtFolder(d.folderId)))return xtError('分类权限已变化，请重新选择有权分类。');if(xtAll().some(t=>t.id!==d.id&&(t.folderId||'xt-mine')===d.folderId&&t.name.trim()===d.name.trim()))return xtError('此分类中已有同名模板，请修改名称。','#xt-template-name');if(!d.rules.length)return xtError('请至少添加一个提取字段。');const names=new Set();for(let i=0;i<d.rules.length;i++){const name=d.rules[i].name.trim();if(!name)return xtError('第 '+(i+1)+' 个字段尚未填写名称。','#xt-field-name-'+i);if(names.has(name.toLowerCase()))return xtError('字段“'+name+'”重复，请使用不同名称。','#xt-field-name-'+i);names.add(name.toLowerCase());}return true;}
function xtPaintEditor(focusId){const old=$('.xt-editor-table-scroll'),top=old?.scrollTop||0,left=old?.scrollLeft||0;paintModal();const table=$('.xt-editor-table-scroll');if(table){table.scrollTop=top;table.scrollLeft=left;}const target=focusId?document.getElementById(focusId):null;if(target){target.focus({preventScroll:true});const tr=target.closest('tr');if(table&&tr){const r=tr.getBoundingClientRect(),v=table.getBoundingClientRect(),head=table.querySelector('thead')?.getBoundingClientRect().height||0;if(r.top<v.top+head)table.scrollTop-=v.top+head-r.top;else if(r.bottom>v.bottom)table.scrollTop+=r.bottom-v.bottom;}}}
function xtSave(){const d=modalData.draft,t=d.id&&xtFind(d.id);if(d.id&&(!t||!xtCanEdit(t)))return xtError('权限已变化，不能保存此模板。');if(!xtValidateDraft(d))return;const folder=xtFolder(d.folderId),obj={...(t||{}),id:d.id||'xt-personal-'+crypto.randomUUID(),toolId:'extract',name:d.name.trim(),description:d.description.trim(),folderId:d.folderId,rules:d.rules.map(r=>xtRule(r.name.trim(),r.description.trim())),prompt:d.prompt||'依据原文逐项提取，未载明的内容如实标注。',owner:t?.owner||xtIdentity(),updatedAt:new Date().toISOString()};if(d.config){obj.config=structuredClone(d.config);obj.config.fieldDefs=obj.rules.map(r=>({...r,description:r.description||'提取原文中的'+r.name+'，未载明时标注未提取到。'}));obj.config.fields=obj.rules.map(r=>r.name);}if(folder.system){const i=xtCatalog.system.findIndex(x=>x.id===obj.id);if(i<0)xtCatalog.system.push(obj);else xtCatalog.system[i]=obj;}else{const i=state.templates.findIndex(x=>x.id===obj.id);if(i<0)state.templates.push(obj);else state.templates[i]=obj;}const keepList=!!d.id&&state.view==='templates'&&xtUnder(d.folderId,xtView.folder),scroll=modalData.listScroll||0;if(!keepList){xtView.folder=d.folderId;xtView.query='';xtView.draftQuery='';xtView.page=1;}xtPersist();xtBase.closeModal();render();if(keepList){const table=$('.xt-table-scroll');if(table)table.scrollTop=scroll;}toast('提取模板已保存，可在信息提取中使用。');}
function xtExport(t){if(!t)return toast('模板已不存在。');download(t.name+'-提取模板.json',JSON.stringify({template_name:t.name,template_desc:t.description||'',prompt:JSON.stringify(xtFields(t)),...(t.templateType!=null?{template_type:t.templateType}:{}),template_classification:t.category||(t.system?'public':'personal'),directory_path:xtPath(t.folderId||'xt-mine')},null,2),'application/json;charset=utf-8');}
function xtImport(){try{const raw=$('#template-import-json').value;if(new TextEncoder().encode(raw).length>2*1024*1024)throw Error('配置文件不能超过2MB。');if(/"(__proto__|prototype|constructor)"\s*:/.test(raw))throw Error('配置包含不允许的属性。');const x=JSON.parse(raw);let rules;if(x.schemaVersion===2){if(x.toolId!=='extract')throw Error('此处仅导入信息提取模板；其他工具方案请在对应工具使用。');validateImportedConfig('extract',x.config);rules=x.config.fieldDefs;}else{rules=Array.isArray(x.rules)?x.rules:typeof x.prompt==='string'?JSON.parse(x.prompt):null;}if(!Array.isArray(rules)||!rules.length||rules.length>200||rules.some(r=>!r||typeof r.name!=='string'||(r.description!=null&&typeof r.description!=='string')))throw Error('需要包含1至200个字段，每个字段应有name及可选description。');const name=x.template_name||x.name;if(typeof name!=='string'||!name.trim())throw Error('配置缺少模板名称。');const description=x.template_desc||x.description||'';if(typeof description!=='string')throw Error('模板描述应为文字。');const t={name,description,rules,prompt:x.schemaVersion===2?x.prompt:'',config:x.schemaVersion===2?x.config:null};xtOpenEditor(t,true);modalData.draft.name=xtUniqueName(name+' · 导入',modalData.draft.folderId);modalData.initial=JSON.stringify(modalData.draft);paintModal();toast('配置已读取，请核对字段后保存。');}catch(e){$('#xt-import-error').textContent='导入失败：'+e.message;}}
function xtAppliedFields(t){return xtFields(t).map(r=>({name:r.name,description:r.description.trim()||'提取原文中的'+r.name+'，保留原始单位及限定条件；未载明时标注未提取到。'}));}
function xtBeginUse(t,from=null){if(!t||!xtFields(t).length)return toast('模板不存在或没有提取字段。');openModal('xt-apply',{id:t.id,from});}
function xtApply(){const t=xtFind(modalData.id);if(!t||!xtFolder(t.folderId||'xt-mine'))return toast('模板已不存在，请重新选择。');const w=ws('extract'),fields=xtAppliedFields(t);if(!fields.length||fields.some(r=>!r.name.trim())||new Set(fields.map(r=>r.name)).size!==fields.length)return toast('字段不完整或存在重名，请先修订模板。');w.config.fieldDefs=structuredClone(fields);w.config.fields=fields.map(r=>r.name);w.config.template=t.name;w.config.extractionTemplateId=t.id;if(t.config?.stages?.extract){w.config.stages.extract=structuredClone(t.config.stages.extract);w.config.prompt=t.config.prompt||t.prompt||w.config.prompt;}w.taskId=null;w.tab='preview';if(!w.ids.length)w.ids=libSelected().filter(d=>!libEligible(d,'extract')).map(d=>d.id);w.preview=w.ids[0]||null;xtBase.closeModal();nav('tool','extract');toast('已应用 '+fields.length+' 个提取字段，请添加资料并执行分析。');}
configPanel=function(){const node=document.createElement('div');node.innerHTML=xtBase.configPanel();const manage=node.querySelector('[data-action="nav-templates"]');if(state.toolId!=='extract'){manage?.remove();return node.innerHTML;}if(manage)manage.textContent='管理提取模板';const c=currentConfig(),select=node.querySelector('[data-config="template"]');if(select){const selected=xtFind(c.extractionTemplateId)||xtAll().find(t=>t.name===c.template),same=selected&&JSON.stringify(xtAppliedFields(selected))===JSON.stringify(c.fieldDefs),current=!!selected&&same;select.removeAttribute('data-config');select.dataset.xtChange='template';select.setAttribute('aria-label','选择提取模板');select.innerHTML=(!current?'<option value="__current__">'+E(c.template)+' · 本次配置</option>':'')+['system','personal'].map(group=>'<optgroup label="'+(group==='system'?'系统模板':'个人模板')+'">'+xtAll().filter(t=>!!t.system===(group==='system')).map(t=>'<option value="'+E(t.id)+'" '+(current&&t.id===selected.id?'selected':'')+'>'+E(t.name)+'</option>').join('')+'</optgroup>').join('');const label=select.closest('.config-section')?.querySelector('.field-label');if(label)label.textContent='提取模板';}return node.innerHTML;};
function xtModalFields(p){const t=xtFind(p.id);if(!t)return modalFrame('模板已不存在','','<p>请关闭后重新选择模板。</p>',B('关闭','close-modal'),'medium');const fields=xtFields(t),shown=fields.map((r,i)=>({...r,index:i+1})).filter(r=>!p.query||(r.name+' '+r.description).toLowerCase().includes(p.query.toLowerCase()));return modalFrame(E(t.name),E(xtPath(t.folderId||'xt-mine')),'<div class="xt-fields-intro"><p>'+E(t.description||'按字段名称和提取说明，从所选资料中整理信息。')+'</p><div class="row"><strong>'+fields.length+' 个提取字段</strong><input id="xt-field-query" aria-label="搜索字段或提取说明" data-xt-input="field-query" value="'+E(p.query||'')+'" placeholder="搜索字段或提取说明"></div></div><div class="xt-fields-table-scroll">'+simpleTable(['序号','字段名称','提取说明'],shown.map(r=>[r.index,E(r.name),E(r.description||'按字段名称提取')]),true)+(!shown.length?'<p class="xt-empty">没有匹配的字段。</p>':'')+'</div>',B('关闭','close-modal')+B('导出配置','xt-export','sm','data-id="'+E(t.id)+'"')+(xtCanEdit(t)?B('编辑模板','xt-edit','sm','data-id="'+E(t.id)+'"'):B('复制为个人模板','xt-copy','sm','data-id="'+E(t.id)+'"'))+B('使用模板','xt-use','primary','data-id="'+E(t.id)+'"'),'xt-fields-dialog');}
modalContent=function(){
 const p=modalData;
 if(modal==='xt-fields')return xtModalFields(p);
 if(modal==='xt-editor'){const d=p.draft,existing=d.id&&xtFind(d.id),editable=!d.id||xtCanEdit(existing);return modalFrame(d.id?'编辑提取模板':d.copySource?'复制为个人模板':'新建提取模板','字段名称决定输出列，提取说明明确取值口径。','<div class="xt-editor-meta"><label class="field"><span>模板名称 <b class="red">*</b></span><input id="xt-template-name" data-xt-edit="name" value="'+E(d.name)+'" maxlength="100" placeholder="输入能说明用途的模板名称"></label><label class="field"><span>所属分类</span>'+(d.id?'<input value="'+E(xtPath(d.folderId))+'" readonly>':'<select id="xt-template-folder" data-xt-edit="folderId">'+(xtFolder(d.folderId)?.system&&xtAdmin()?'<option value="'+E(d.folderId)+'" selected>'+E(xtPath(d.folderId))+'</option>':'')+xtPersonalOptions(d.folderId)+'</select>')+'</label><label class="field xt-editor-description"><span>模板描述 <span class="muted">（选填）</span></span><textarea id="xt-template-description" rows="2" data-xt-edit="description" placeholder="说明适用资料和用途">'+E(d.description)+'</textarea></label></div><div class="xt-editor-fields-head"><h3>提取字段 <strong>'+d.rules.length+'</strong></h3><span>按列表顺序输出；说明可留空，默认按字段名称提取</span>'+B(I('plus','icon-sm')+'添加字段','xt-add-field','soft sm',d.rules.length>=200?'disabled':'')+'</div><div class="xt-editor-table-scroll"><table class="table xt-editor-table"><thead><tr><th>序号</th><th>字段名称 <b class="red">*</b></th><th>提取说明</th><th>调整</th></tr></thead><tbody>'+d.rules.map((r,i)=>'<tr><td>'+(i+1)+'</td><td><input id="xt-field-name-'+i+'" aria-label="字段'+(i+1)+'名称" data-xt-field="name" data-index="'+i+'" value="'+E(r.name)+'" placeholder="字段名称" maxlength="100"></td><td><textarea aria-label="字段'+(i+1)+'提取说明" data-xt-field="description" data-index="'+i+'" rows="2" placeholder="说明从哪里提取、取值口径或输出要求">'+E(r.description)+'</textarea></td><td><div class="row">'+B(I('back','icon-sm'),'xt-field-up','ghost sm xt-move-up','data-index="'+i+'" aria-label="上移字段'+(i+1)+'" '+(i===0?'disabled':''))+B(I('chevron','icon-sm'),'xt-field-down','ghost sm xt-move-down','data-index="'+i+'" aria-label="下移字段'+(i+1)+'" '+(i===d.rules.length-1?'disabled':''))+B(I('trash','icon-sm'),'xt-remove-field','ghost danger sm','data-index="'+i+'" aria-label="删除字段'+(i+1)+'"')+'</div></td></tr>').join('')+'</tbody></table>'+(!d.rules.length?'<div class="xt-empty">尚未添加字段，请添加至少一个字段。</div>':'')+'</div><div id="xt-editor-error" class="error" role="alert">'+E(p.error||'')+'</div>','<span class="xt-editor-footer-note">保存模板不会改写已执行任务或当前工作区配置。</span><div class="row">'+B('取消','close-modal')+B('保存模板','xt-save','primary',editable?'':'disabled')+'</div>','xt-editor-dialog');}
 if(modal==='xt-discard')return modalFrame('放弃未保存的修改？','','<p>当前修改尚未保存，关闭后不会写入模板。</p>',B('继续编辑','xt-continue-edit')+B('放弃修改','xt-confirm-discard','danger'),'small');
 if(modal==='xt-apply'){const t=xtFind(p.id);return modalFrame('使用提取模板',E(t?.name||'模板已不存在'),'<p>将应用此模板的 <strong>'+(t?xtFields(t).length:0)+'</strong> 个字段到信息提取。当前字段将被替换，已执行任务和原模板保留。</p>',B('取消','close-modal')+B('应用并前往信息提取','xt-apply-confirm','primary',t?'':'disabled'),'medium');}
 if(modal==='xt-folder-menu'){const f=xtFolder(p.id);return modalFrame('管理分类',E(xtPath(p.id)),'<div class="column">'+B(I('folderPlus','icon-sm')+'新建子分类','xt-new-folder','sm','data-id="'+E(p.id)+'" '+(!xtFolderEdit(f)?'disabled':''))+(f?.parent?B(I('edit','icon-sm')+'重命名','xt-rename-folder','sm','data-id="'+E(p.id)+'" '+(!xtFolderEdit(f)?'disabled':''))+B(I('trash','icon-sm')+'删除分类','xt-delete-folder','danger sm','data-id="'+E(p.id)+'" '+(!xtFolderEdit(f)?'disabled':'')):'')+'</div>',B('关闭','close-modal'),'small');}
 if(modal==='xt-folder-name')return modalFrame(p.rename?'重命名分类':'新建子分类',E(xtPath(p.rename?xtFolder(p.id)?.parent:p.id)),'<label class="field"><span>分类名称 <b class="red">*</b></span><input id="xt-folder-name" value="'+E(p.value||'')+'" maxlength="100" placeholder="输入分类名称"></label><p class="error" id="xt-folder-error" role="alert"></p>',B('取消','close-modal')+B('保存','xt-save-folder','primary'),'small');
 if(modal==='xt-delete'){const t=xtFind(p.id);return modalFrame('删除提取模板',E(t?.name||''),'<p>确认删除此模板？已执行任务和已应用到工作区的字段副本仍保留。</p>',B('取消','close-modal')+B('确认删除','xt-confirm-delete','danger'),'small');}
 if(modal==='xt-delete-folder'){const children=xtCatalog.folders.filter(f=>f.parent===p.id).length,count=xtAll().filter(t=>xtUnder(t.folderId||'xt-mine',p.id)).length;return modalFrame('删除分类',E(xtPath(p.id)),children||count?'<p>此分类含 <strong>'+children+'</strong> 个子分类、<strong>'+count+'</strong> 个模板。请先清空内容，再删除分类。</p>':'<p>确认删除此空分类？</p>',B('取消','close-modal')+B('确认删除','xt-confirm-delete-folder','danger',children||count?'disabled':''),'small');}
 if(modal==='xt-import')return modalFrame('导入提取模板','读取配置后可核对名称和字段，保存前不写入模板。','<label class="field"><span>选择配置文件</span><input id="xt-import-file" type="file" accept=".json,application/json" aria-label="选择提取模板配置文件"></label><label class="field"><span>配置内容</span><textarea id="template-import-json" rows="8" placeholder="可选择JSON文件，或粘贴导出的提取模板配置"></textarea></label><p class="hint">支持原模板字段配置及信息提取工具导出的配置，文件不超过2MB。</p><p class="error" id="xt-import-error" role="alert"></p>',B('取消','close-modal')+B('读取配置','xt-import-read','primary'),'xt-import-dialog');
 let html=xtBase.modalContent();if(modal==='mobile-nav')html=html.replace('>模板管理<','>提取模板<');return html;
};
function xtBack(p){if(p.from)openModal(p.from.type,p.from.data);else{xtBase.closeModal();if(state.view==='tool')render();}}
handleAction=function(action,el){const id=el?.dataset.id;
 if(['template-detail','use-template','delete-template'].includes(action)&&xtFind(id))action=({'template-detail':'xt-fields','use-template':'xt-use','delete-template':'xt-delete'})[action];
 if(action==='new-template'&&state.view==='templates')action='xt-new';
 if(action==='v2-template-import'&&state.view==='templates'){openModal('xt-import');return;}
 if(action==='save-template'&&state.toolId==='extract'){const c=currentConfig();xtOpenEditor({name:c.template+' · 我的版本',rules:c.fieldDefs,description:'',prompt:c.prompt,config:structuredClone(c)},true);return;}
 if(!action.startsWith('xt-'))return xtBase.handleAction(action,el);
 const t=id&&xtFind(id),f=id&&xtFolder(id),from=modal==='xt-fields'?{type:modal,data:structuredClone(modalData)}:null;
 switch(action){
 case 'xt-refresh':xtRefresh();toast('分类与模板已刷新。');break;
 case 'xt-folder':xtView.folder=id;xtView.query='';xtView.draftQuery='';xtView.page=1;xtView.mobileTree=false;xtRefresh();break;
 case 'xt-toggle-folder':xtView.closed=xtView.closed.includes(id)?xtView.closed.filter(x=>x!==id):[...xtView.closed,id];xtRefresh();break;
 case 'xt-open-tree':xtView.mobileTree=true;render();break;
 case 'xt-close-tree':xtView.mobileTree=false;render();break;
 case 'xt-search':xtView.query=xtView.draftQuery;xtView.page=1;xtRefresh();break;
 case 'xt-clear-search':xtView.query='';xtView.draftQuery='';xtView.page=1;xtRefresh();break;
 case 'xt-prev':xtView.page--;xtRefresh();break;
 case 'xt-next':xtView.page++;xtRefresh();break;
 case 'xt-new':xtOpenEditor();break;
 case 'xt-fields':if(t)openModal('xt-fields',{id,query:''});break;
 case 'xt-edit':if(t)xtOpenEditor(t,false,from);break;
 case 'xt-copy':if(t)xtOpenEditor(t,true,from);break;
 case 'xt-add-field':if(modal!=='xt-editor')return;if(modalData.draft.rules.length<200){modalData.draft.rules.push(xtRule(''));xtPaintEditor('xt-field-name-'+(modalData.draft.rules.length-1));}break;
 case 'xt-remove-field':if(modal==='xt-editor'){const index=+el.dataset.index;modalData.draft.rules.splice(index,1);xtPaintEditor('xt-field-name-'+Math.min(index,modalData.draft.rules.length-1));if(!modalData.draft.rules.length)$('[data-action="xt-add-field"]')?.focus();}break;
 case 'xt-field-up':case 'xt-field-down':if(modal==='xt-editor'){const rows=modalData.draft.rules,i=+el.dataset.index,j=i+(action==='xt-field-up'?-1:1);if(j>=0&&j<rows.length){[rows[i],rows[j]]=[rows[j],rows[i]];xtPaintEditor('xt-field-name-'+j);}}break;
 case 'xt-save':if(modal==='xt-editor')xtSave();break;
 case 'xt-continue-edit':openModal('xt-editor',modalData.back);break;
 case 'xt-confirm-discard':xtBack(modalData.back);break;
 case 'xt-use':xtBeginUse(t,from);break;
 case 'xt-apply-confirm':if(modal==='xt-apply')xtApply();break;
 case 'xt-export':xtExport(t);break;
 case 'xt-import-read':if(modal==='xt-import')xtImport();break;
 case 'xt-folder-menu':if(xtFolderEdit(f))openModal('xt-folder-menu',{id});break;
 case 'xt-new-folder':if(xtFolderEdit(f))openModal('xt-folder-name',{id,rename:false});break;
 case 'xt-rename-folder':if(xtFolderEdit(f)&&f.parent)openModal('xt-folder-name',{id,rename:true,value:f.name});break;
 case 'xt-save-folder':{const p=modalData,folder=xtFolder(p.id),name=$('#xt-folder-name').value.trim(),parent=p.rename?folder?.parent:p.id,err=$('#xt-folder-error');if(!folder||!xtFolderEdit(folder))return err.textContent='分类权限已变化。';if(!name||/[\\/]/.test(name))return err.textContent='请填写分类名称，不能包含斜杠。';if(xtCatalog.folders.some(x=>x.parent===parent&&x.id!==(p.rename?p.id:null)&&x.name===name))return err.textContent='同一层级已存在此名称。';if(p.rename)folder.name=name;else xtCatalog.folders.push({id:'xt-folder-'+crypto.randomUUID(),parent:p.id,name,system:folder.system,owner:xtIdentity()});xtPersist();xtBase.closeModal();render();toast('分类已保存。');break;}
 case 'xt-delete':if(t&&xtCanEdit(t))openModal('xt-delete',{id});break;
 case 'xt-confirm-delete':{const old=xtFind(modalData.id);if(!old||!xtCanEdit(old))return toast('权限已变化，无法删除此模板。');if(old.system)xtCatalog.system=xtCatalog.system.filter(x=>x.id!==old.id);else state.templates=state.templates.filter(x=>x.id!==old.id);xtPersist();xtBase.closeModal();render();toast('提取模板已删除，任务和工作区副本保留。');break;}
 case 'xt-delete-folder':if(f?.parent&&xtFolderEdit(f))openModal('xt-delete-folder',{id});break;
 case 'xt-confirm-delete-folder':{const old=xtFolder(modalData.id);if(!old?.parent||!xtFolderEdit(old)||xtCatalog.folders.some(x=>x.parent===old.id)||xtAll().some(x=>xtUnder(x.folderId||'xt-mine',old.id)))return toast('分类不是空分类，或权限已变化。');xtCatalog.folders=xtCatalog.folders.filter(x=>x.id!==old.id);if(xtView.folder===old.id)xtView.folder=old.parent;xtRefresh();xtBase.closeModal();render();break;}
 }
};
closeModal=function(){if(modal==='xt-editor'){const p=modalData;if(JSON.stringify(p.draft)!==p.initial){openModal('xt-discard',{back:p});return;}xtBack(p);return;}if(modal==='xt-discard'){openModal('xt-editor',modalData.back);return;}if(modal==='xt-apply'){xtBack(modalData);return;}xtBase.closeModal();};
window.addEventListener('input',e=>{const el=e.target;if(el.dataset.xtInput==='folder-query'){e.stopImmediatePropagation();const pos=el.selectionStart;xtView.folderQuery=el.value;render();const input=$('#xt-folder-query');input?.focus();try{input?.setSelectionRange(pos,pos);}catch{}return;}if(el.dataset.xtInput==='query'){e.stopImmediatePropagation();xtView.draftQuery=el.value;return;}if(el.dataset.xtInput==='field-query'&&modal==='xt-fields'){e.stopImmediatePropagation();modalData.query=el.value;paintModal();$('#xt-field-query')?.focus();return;}if(modal==='xt-editor'&&(el.dataset.xtEdit||el.dataset.xtField)){e.stopImmediatePropagation();if(el.dataset.xtEdit)modalData.draft[el.dataset.xtEdit]=el.value;if(el.dataset.xtField)modalData.draft.rules[+el.dataset.index][el.dataset.xtField]=el.value;return;}},true);
window.addEventListener('change',async e=>{const el=e.target,k=el.dataset.xtChange;if(k){e.stopImmediatePropagation();if(k==='template'){if(isLocked()||el.value==='__current__')return;xtBeginUse(xtFind(el.value));return;}if(k==='size'){xtView.size=Number(el.value);xtView.page=1;xtRefresh();}if(k==='page'){const n=Number(el.value),pages=Math.max(1,Math.ceil(xtList().length/xtView.size));if(!Number.isInteger(n)||n<1||n>pages){el.value=xtView.page;return;}xtView.page=n;xtRefresh();}return;}if(el.dataset.xtEdit&&modal==='xt-editor'){e.stopImmediatePropagation();modalData.draft[el.dataset.xtEdit]=el.value;return;}if(el.id==='xt-import-file'&&modal==='xt-import'){e.stopImmediatePropagation();const p=modalData,file=el.files[0];if(!file)return;if(file.size>2*1024*1024){$('#xt-import-error').textContent='配置文件不能超过2MB。';return;}const text=await file.text();if(modal==='xt-import'&&modalData===p)$('#template-import-json').value=text;}},true);
window.addEventListener('keydown',e=>{if(e.target.id==='xt-template-query'&&e.key==='Enter'){e.preventDefault();e.stopImmediatePropagation();xtView.query=xtView.draftQuery;xtView.page=1;xtRefresh();$('#xt-template-query')?.focus();}},true);
document.addEventListener('click',e=>{const d=e.target.closest('.xt-page details');if(e.target.closest('button[data-action]')&&d)d.open=false;document.querySelectorAll('.xt-page details[open]').forEach(x=>{if(!x.contains(e.target))x.open=false;});},true);
document.addEventListener('toggle',e=>{const d=e.target;if(!d.matches?.('.xt-page details')||!d.open)return;document.querySelectorAll('.xt-page details[open]').forEach(x=>{if(x!==d)x.open=false;});const menu=d.querySelector('.lib-menu'),rect=d.querySelector('summary').getBoundingClientRect();if(!menu)return;menu.style.position='fixed';menu.style.right='auto';menu.style.bottom='auto';menu.style.left=Math.max(8,Math.min(innerWidth-menu.offsetWidth-8,rect.right-menu.offsetWidth))+'px';menu.style.top=Math.max(8,rect.bottom+menu.offsetHeight+6>innerHeight?rect.top-menu.offsetHeight-6:rect.bottom+6)+'px';},true);
window.addEventListener('resize',()=>document.querySelectorAll('.xt-page details[open]').forEach(d=>d.open=false));
window.addEventListener('keydown',e=>{if(e.key!=='Escape'||modal||state.view!=='templates')return;const open=document.querySelector('.xt-page details[open]');if(open){e.preventDefault();e.stopImmediatePropagation();open.open=false;open.querySelector('summary')?.focus();}else if(xtView.mobileTree){e.preventDefault();e.stopImmediatePropagation();xtView.mobileTree=false;render();$('[data-action="xt-open-tree"]')?.focus();}},true);
window.addEventListener('scroll',e=>{if(e.target.closest?.('.xt-page .lib-menu'))return;document.querySelectorAll('.xt-page details[open]').forEach(d=>d.open=false);},true);
render();
